{
  "items": [
    {
      "name": "ThreeAPFree.le_rothNumberNat",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ {k n : ℕ} (s : Finset ℕ), ThreeAPFree ↑s → (∀ x ∈ s, x < n) → s.card = k → k ≤ rothNumberNat n"
    },
    {
      "name": "Behrend.roth_lower_bound",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, ↑N * Real.exp (-4 * √(Real.log ↑N)) ≤ ↑(rothNumberNat N)"
    },
    {
      "name": "Behrend.bound_aux",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {n d : ℕ}, d ≠ 0 → 2 ≤ n → ↑d ^ (n - 2) / ↑n ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "Behrend.roth_lower_bound_explicit",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {N : ℕ}, 4096 ≤ N → ↑N * Real.exp (-4 * √(Real.log ↑N)) < ↑(rothNumberNat N)"
    },
    {
      "name": "Behrend.bound_aux'",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ (n d : ℕ), ↑(d ^ n) / ↑(n * d ^ 2) ≤ ↑(rothNumberNat ((2 * d - 1) ^ n))"
    },
    {
      "name": "addRothNumber_le",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : DecidableEq α] [inst_1 : AddMonoid α] (s : Finset α), addRothNumber s ≤ s.card"
    },
    {
      "name": "rothNumberNat_add_le",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ (M N : ℕ), rothNumberNat (M + N) ≤ rothNumberNat M + rothNumberNat N"
    },
    {
      "name": "rothNumberNat_def",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Defs",
      "kind": "theorem",
      "type": "∀ (n : ℕ), rothNumberNat n = addRothNumber (Finset.range n)"
    }
  ]
}
